export function Programme({
  name = "{{name}}",
  status = "{{status}}",
  projectsShown = {{projectsShown}},
  sponsor = "{{sponsor}}",
  accent = "{{accent}}",
}) {
  const projects = [
    { label: "Identity verification revamp", note: "on track" },
    { label: "Fraud signals pipeline", note: "on track" },
    { label: "Support macro rewrite", note: "at risk" },
  ].slice(0, projectsShown);
  const palette = {
    "on-track": { background: "color-mix(in srgb, #A8E6C1 45%, #FAF7F2)", color: "#205c37", icon: <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><circle cx="8" cy="8" r="6.3" /><path d="M5.3 8.2 7 9.9l3.6-4" /></svg> },
    "at-risk": { background: "color-mix(in srgb, #E8A020 25%, #FAF7F2)", color: "#7a5410", icon: <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><path d="M8 2 1.3 14h13.4L8 2z" /><path d="M8 6.6v3.2" /><circle cx="8" cy="11.4" r=".9" fill="currentColor" stroke="none" /></svg> },
    delayed: { background: "color-mix(in srgb, #F5C2E0 45%, #FAF7F2)", color: "#7a2f57", icon: <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><path d="M5 1.5h6L14.5 5v6L11 14.5H5L1.5 11V5z" /><path d="M6 6v4M10 6v4" /></svg> },
  }[status] ?? {};
  return (
    <section aria-labelledby="programme-heading-react" style={{ maxWidth: 520, padding: "18px 20px", borderRadius: 12, background: "#FAF7F2", border: "1px solid #24143022", boxSizing: "border-box", font: "14px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <header style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 10, borderLeft: "3px solid " + accent, paddingLeft: 10, marginBottom: 10 }}>
        <div>
          <h3 id="programme-heading-react" style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>{name}</h3>
          <p style={{ margin: "2px 0 0", fontSize: 12.5, color: "#241430b3" }}>Sponsored by {sponsor}</p>
        </div>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, fontWeight: 600, padding: "4px 9px", borderRadius: 999, textTransform: "capitalize", flexShrink: 0, background: palette.background, color: palette.color }}>
          {palette.icon}
          <span>{status}</span>
        </span>
      </header>
      <p style={{ margin: "0 0 10px", fontSize: 13, fontWeight: 600 }}>{projectsShown} projects in this programme</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 8 }}>
        {projects.map((p) => (
          <li key={p.label} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, padding: "8px 10px", borderRadius: 8, background: "#24143008" }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", background: accent, flexShrink: 0 }} />
            {p.label}
            <em style={{ fontStyle: "normal", color: "#241430b3", marginLeft: 4 }}>&mdash; {p.note}</em>
          </li>
        ))}
      </ul>
    </section>
  );
}
